Settings = {}

---@class Global
Global = {}
Global.setting = {}

local function loadGlobalSetting()
    local settingPath = FileUtil:getSettingPath() .. "setting.json"
    local file = io.open(settingPath, 'r')
    if not file then
        LogUtil.logInfo("[Global:loadGlobalSetting] not file , settingPath = ", settingPath)
        return
    end
    local content = file:read("*a")
    file:close()
    Global.setting = json.decode(content)
end

local function loadPluginSetting()
    local settingPath = FileUtil:getMapPath() .. "plugins_setting.json"
    local file = io.open(settingPath, 'r')
    if not file then
        settingPath = FileUtil:getSettingPath() .. "plugins_setting.json"
        file = io.open(settingPath, 'r')
        if not file then
            LogUtil.logInfo("[Global:loadPluginSetting] not file , settingPath = ", settingPath)
            return
        end
    end
    local content = file:read("*a")
    file:close()
    Global.setting.plugins = json.decode(content)
end

local function loadPidPacketMapping()
    local path = FileUtil:getSettingPath() .. "S2CPidPacket.ini"
    local file = io.open(path, "r")
    if file then
        local Name2HashId = T(Global, "S2CPid_Name2HashId")
        local HashId2Name = T(Global, "S2CPid_HashId2Name")
        local content = file:read("*a")
        file:close()
        local lines = StringUtil.split(content, "\n")
        for _, line in pairs(lines) do
            local info = StringUtil.split(line, "=")
            Name2HashId[info[1]] = tonumber(info[2])
            HashId2Name[tonumber(info[2])] = info[1]
        end
    end
    path = FileUtil:getSettingPath() .. "C2SPidPacket.ini"
    file = io.open(path, "r")
    if file then
        local Name2HashId = T(Global, "C2SPid_Name2HashId")
        local HashId2Name = T(Global, "C2SPid_HashId2Name")
        local content = file:read("*a")
        file:close()
        local lines = StringUtil.split(content, "\n")
        for _, line in pairs(lines) do
            local info = StringUtil.split(line, "=")
            Name2HashId[info[1]] = tonumber(info[2])
            HashId2Name[tonumber(info[2])] = info[1]
        end
    end
end

function Global:loadSetting()
    loadGlobalSetting()
    loadPluginSetting()
    loadPidPacketMapping()
end

---@param tb table
---@param key string
---@param value table
function T(tb, key, value)
    local ret = tb[key]
    if ret ~= nil then
        return value or ret
    end
    if value == nil then
        value = {}
    end
    tb[key] = value
    return value
end

